import sys
sys.path.insert(0,"_tools")
import kb_mcp, backlog
def run(code):
    def fake(argv):
        print("planted output")
        return code
    backlog.main = fake
    one, two = [], []
    for c in kb_mcp.BACKLOG_COMMANDS:
        if c == "usage":
            continue
        try:
            r = kb_mcp.kb_backlog({"command": c, "args": []})
            if code == 1 and not r.endswith("(exit 1)"):
                one.append(c)
            if code == 2:
                two.append(c)
        except kb_mcp.ToolError:
            if code == 1:
                one.append(c)
    return one, two
a, _ = run(1)
_, b = run(2)
print("exit 1 not text:", a, "exit 2 not an error:", b)
sys.exit(1 if a or b else 0)
